const CACHE='fridgeful-camera-a1522a0e5d80';const FILES=["/camera/","/camera/index.html","/camera/manifest.webmanifest","/camera/brand.svg","/camera/fridge-mark.svg","/camera/icon-192.png","/camera/icon-512.png","/camera/apple-touch-icon.png","/camera/assets/index-DS3TY3KE.js","/camera/assets/index-Dads3dlu.css"];self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)));self.skipWaiting()});self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k.startsWith('fridgeful-camera-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==location.origin||!FILES.includes(u.pathname))return;if(e.request.mode==='navigate'){e.respondWith(fetch(e.request).catch(()=>caches.match('/camera/index.html')))}else e.respondWith(caches.match(e.request).then(r=>r||fetch(e.request)))});